create table public.feature_flags(key citext primary key,description text not null default '',is_enabled boolean not null default false,scope jsonb not null default '{}'::jsonb,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint feature_flag_scope check(jsonb_typeof(scope)='object'));create table public.analytics_events(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,event_name text not null,entity_type text,entity_id uuid,session_id uuid,metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default timezone('utc',now()),constraint analytics_metadata check(jsonb_typeof(metadata)='object'));create table public.daily_metrics(metric_date date not null,campus_id uuid references public.campuses(id) on delete restrict,metric_key text not null,metric_value numeric not null,updated_at timestamptz not null default timezone('utc',now()),primary key(metric_date,campus_id,metric_key));create index analytics_events_time_idx on public.analytics_events(occurred_at desc);alter table public.feature_flags enable row level security;alter table public.analytics_events enable row level security;alter table public.daily_metrics enable row level security;create policy feature_flags_read on public.feature_flags for select to authenticated using(true);create policy feature_flags_manage on public.feature_flags for all to authenticated using(public.has_permission('features.manage')) with check(public.has_permission('features.manage'));create policy analytics_read on public.analytics_events for select to authenticated using(public.has_permission('analytics.read'));create policy metrics_read on public.daily_metrics for select to authenticated using(public.has_permission('analytics.read'));
